#include <iostream>
#include <vector>
struct Result {
    int value = 0, rejected = 0;
    bool operator==(const Result &) const = default;
};
Result replay(const std::vector<int> &trace) {
    Result r;
    for (int x : trace) {
        if (x < -10 || x > 10 || r.value + x < 0 || r.value + x > 10) {
            ++r.rejected;
        } else {
            r.value += x;
        }
    }
    return r;
}
Result mutant(const std::vector<int> &trace) {
    Result r;
    for (int x : trace) {
        if (x < -10 || x > 10 || r.value + x < 0 || r.value + x > 9) {
            ++r.rejected;
        } else {
            r.value += x;
        }
    }
    return r;
}
int main() {
    const auto a = replay({10}), b = mutant({10});
    std::cout << "original " << a.value << ' ' << a.rejected << '\n';
    std::cout << "mutant " << b.value << ' ' << b.rejected << '\n';
    return a.value == 10 && a.rejected == 0 && b != a ? 0 : 1;
}

